import re,sys
B='/home/claude/customer-support-prd/prd/03 - PRD Sections/'
A=B+'PRD-05a - Chat Page.md'; Bb=B+'PRD-05b - Admin Panel.md'
def rw(p,f):
    s=open(p,encoding='utf-8').read(); t=f(s); assert t!=s,p; open(p,'w',encoding='utf-8').write(t)
def R(s,a,b):
    assert a in s,a[:70]; return s.replace(a,b,1)
def a(s):
    s=R(s,'version: 1.3\n','version: 1.4\n'); s=R(s,'last_updated: 2026-11-19','last_updated: 2026-11-20')
    s=re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+' · 1.4 — CH-52 (آزمون تیمی دوم): سوی پیام‌ها، نام پشتیبان پس از پیوستن، تصویر پیش‌فرض فروشگاه، اسکرول‌بار کادر نوشتن"\n', s, count=1)
    s=R(s,'| ‏یک سوی فهرست (سوی دقیق با تیم طراحی) |','| ‏**سمت راست** فهرست (DEC-302) |')
    s=R(s,'| ‏C2 پیام دستیار | ‏متن دستیار با برچسب فرستنده «دستیار» | ‏سوی دیگر |','| ‏C2 پیام دستیار | ‏متن دستیار با برچسب فرستنده «دستیار» | ‏**سمت چپ** فهرست (DEC-302) |')
    s=R(s,'| ‏C3 پیام پشتیبان | ‏متن ادمین با برچسب «پشتیبان فروشگاه»؛ ظاهری متمایز از C2 | ‏همان سوی C2 | ‏نام ادمین نمایش داده نمی‌شود | ‏US-07-03؛ DEC-94 |',
            '| ‏C3 پیام پشتیبان | ‏متن ادمین؛ زیر پیام «[نام و نام خانوادگی] · پشتیبان فروشگاه»؛ ظاهری متمایز از C2 | ‏سمت چپ، مثل C2 | ‏نام و نام خانوادگی ادمینی که گفت‌وگو را تحویل گرفته نمایش داده می‌شود؛ جای دیگری نام ادمین به مشتری نشان داده نمی‌شود | ‏US-07-03؛ **DEC-303** (جایگزین DEC-94) |')
    s=R(s,'C3 نشانه جدا («پ») دارد','C3 نشانه جدا (نشانه شخص) دارد؛ نشانه فروشگاه تا تعیین حوزه کالا یک تصویر پیش‌فرض عمومی (کیف خرید) است (DEC-305)')
    s=R(s,'| ‏R1 نشان S4 | ‏«پشتیبان فروشگاه در گفت‌وگوست. پیام‌هایتان را همین‌جا بنویسید.»','| ‏R1 نشان S4 | ‏«[نام و نام خانوادگی] از پشتیبانی فروشگاه در گفت‌وگوست. پیام‌هایتان را همین‌جا بنویسید.» (DEC-303)')
    dec=('| ‏DEC-302 | ‏پیام مشتری (C1) سمت راست صفحه و پیام دستیار و پشتیبان (C2، C3) سمت چپ؛ نشانه فرستنده کنار لبه چپ |\n'
         '| ‏DEC-303 | ‏پس از پیوستن پشتیبان، نام و نام خانوادگی او در خط سیستمی پیوستن (C4)، زیر پیام‌هایش (C3) و در نوار R1 ح۷ به مشتری نشان داده می‌شود. جایگزین بخش «نام ادمین نشان داده نمی‌شود» در DEC-94 |\n'
         '| ‏DEC-305 | ‏تا تعیین حوزه کالا (D-01)، نشانه فروشگاه در سرصفحه و کنار پیام دستیار یک تصویر پیش‌فرض عمومی است (کیف خرید)؛ با لوگوی فروشگاه جایگزین می‌شود |\n'
         '| ‏DEC-306 | ‏اسکرول‌بار کادر نوشتن فقط وقتی متن از بیشینه ارتفاع کادر (۴ خط) بیشتر شود دیده می‌شود |\n')
    s=re.sub(r'(\| ‏DEC-297 \|[^\n]*\n)', lambda m: m.group(1)+dec, s, count=1)
    s=re.sub(r'(\| ‏1\.3 \| ‏2026-11-19 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.4 | ‏2026-11-20 | ‏آزمون تیمی دوم (CH-52): C1 راست و C2، C3 چپ (DEC-302)؛ نام پشتیبان پس از پیوستن (DEC-303)؛ نشانه پیش‌فرض فروشگاه (DEC-305)؛ اسکرول‌بار کادر نوشتن (DEC-306) |\n', s, count=1)
    return s
def b(s):
    s=R(s,'version: 1.4\n','version: 1.5\n'); s=R(s,'last_updated: 2026-11-19','last_updated: 2026-11-20')
    s=re.sub(r'(change_note: ".*?)"\n', lambda m: m.group(1)+' · 1.5 — CH-52: «انتظار مشتری» از آخرین پیام بی‌پاسخ مشتری و هشدار «بی‌پاسخ» در ردیف"\n', s, count=1)
    s=R(s,'| ‏زمان | ‏عنوان ستون «انتظار مشتری»: از ارجاع باز فعلی، نسبی;'.replace(';','؛') if False else '| ‏زمان | ‏عنوان ستون «انتظار مشتری»: از ارجاع باز فعلی، نسبی؛',
          '| ‏زمان | ‏عنوان ستون «انتظار مشتری»: از **آخرین پیام بی‌پاسخ مشتری** (در S3 و S4؛ اگر پیام بی‌پاسخی نیست، از ارجاع باز فعلی)، نسبی (DEC-304)؛')
    s=re.sub(r'(\| ‏شناسه \| ‏شناسه کوتاه مکالمه، کم‌رنگ، زیر آخرین پیام \|[^\n]*\n)', lambda m: m.group(1)+'| ‏هشدار «بی‌پاسخ» | ‏ردیف S4 که پیام مشتری ۱۵ دقیقه یا بیشتر بی‌پاسخ مانده: پس‌زمینه هشدار، نوار رنگی در لبه آغاز و برچسب «⚠ بی‌پاسخ» زیر وضعیت؛ از ۳۰ دقیقه به رنگ قرمز. بدون اعلان صوتی یا پیام بیرونی (CON-13) | — | ‏**DEC-304** |\n', s, count=1)
    dec='| ‏DEC-304 | ‏SCR-10: «انتظار مشتری» از آخرین پیام بی‌پاسخ مشتری (S3 و S4)؛ ردیف S4 با ۱۵ دقیقه یا بیشتر بی‌پاسخ هشدار «بی‌پاسخ» می‌گیرد (کهربایی؛ از ۳۰ دقیقه قرمز)؛ بدون اعلان. تکمیل DEC-298 و DEC-301 |\n'
    s=re.sub(r'(\| ‏DEC-301 \|[^\n]*\n)', lambda m: m.group(1)+dec, s, count=1)
    s=re.sub(r'(\| ‏1\.4 \| ‏2026-11-19 \|[^\n]*\n)', lambda m: m.group(1)+'| ‏1.5 | ‏2026-11-20 | ‏هشدار «بی‌پاسخ» و مبنای تازه «انتظار مشتری» در SCR-10 (DEC-304) | ‏CH-52 |\n', s, count=1)
    return s
def m(s):
    s=R(s,'version: 1.7\n','version: 1.8\n'); s=R(s,'last_updated: 2026-11-19','last_updated: 2026-11-20')
    s=R(s,'| ‏1.7 | ‏2026-11-19 | ‏آزمون تیمی پروتوتایپ؛ CH-51 |','| ‏1.8 | ‏2026-11-20 | ‏آزمون تیمی دوم؛ CH-52 |')
    s=R(s,'| ‏PRD-05a - Chat Page | ‏Approved | ‏**1.3 (CH-51)** | ‏2026-11-19 |','| ‏PRD-05a - Chat Page | ‏Approved | ‏**1.4 (CH-52)** | ‏2026-11-20 |')
    s=R(s,'| ‏PRD-05b - Admin Panel | ‏Approved | ‏**1.4 (CH-51)** | ‏2026-11-19 |','| ‏PRD-05b - Admin Panel | ‏Approved | ‏**1.5 (CH-52)** | ‏2026-11-20 |')
    dec=('| ‏DEC-302 | ‏**سوی پیام‌ها:** پیام مشتری سمت راست صفحه گفت‌وگو؛ دستیار و پشتیبان سمت چپ. | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n'
         '| ‏DEC-303 | ‏**نام پشتیبان برای مشتری:** پس از پیوستن، نام و نام خانوادگی ادمینی که گفت‌وگو را تحویل گرفته در خط پیوستن، زیر پیام‌هایش و در نوار ح۷ نمایش داده می‌شود؛ جای دیگری نام ادمین به مشتری نشان داده نمی‌شود. **جایگزین بخش «نام ادمین نشان داده نمی‌شود» در DEC-94** *(همگام‌سازی PRD-04-EP07، PRD-04-DD و PRD-15 در گام بعد — CH-52)* | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n'
         '| ‏DEC-304 | ‏**هشدار «بی‌پاسخ» در صف اقدام:** «انتظار مشتری» از آخرین پیام بی‌پاسخ مشتری (S3 و S4)؛ ردیف S4 با ۱۵ دقیقه یا بیشتر بی‌پاسخ، هایلایت هشدار و برچسب «بی‌پاسخ» می‌گیرد (از ۳۰ دقیقه قرمز)؛ بدون اعلان صوتی یا بیرونی (CON-13). | ‏2026-11-20 | ‏PRD-05b | ‏CH-52 |\n'
         '| ‏DEC-305 | ‏**نشانه پیش‌فرض فروشگاه:** تا تعیین حوزه کالا (D-01؛ احتمالاً پوشاک)، تصویر عمومی کیف خرید؛ با لوگوی فروشگاه جایگزین می‌شود. داده نمونه پروتوتایپ پوشاک می‌ماند. | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n'
         '| ‏DEC-306 | ‏اسکرول‌بار کادر نوشتن مشتری فقط وقتی متن از ۴ خط بیشتر شود. | ‏2026-11-20 | ‏PRD-05a | ‏CH-52 |\n')
    s=re.sub(r'(\| ‏DEC-301 \|[^\n]*\n)', lambda mm: mm.group(1)+dec, s, count=1)
    s=R(s,'| ‏DEC-94 | ‏اطلاع مشتری از تحویل با «پشتیبان فروشگاه به گفت‌وگو پیوست»؛ نام ادمین به مشتری نشان داده نمی‌شود. |','| ‏DEC-94 | ‏اطلاع مشتری از تحویل با «پشتیبان فروشگاه به گفت‌وگو پیوست»؛ نام ادمین به مشتری نشان داده نمی‌شود. *(بخش نام جایگزین‌شده با DEC-303 — CH-52)* |')
    s=re.sub(r'(\| ‏CH-51 \| ‏2026-11-19 \|[^\n]*\n)', lambda mm: mm.group(1)+'| ‏CH-52 | ‏2026-11-20 | ‏**آزمون تیمی دوم (بازخورد سعید، موبایل مشتری):** DEC-302 تا DEC-306 ثبت شد؛ PRD-05a 1.4، PRD-05b 1.5. DEC-94 بخش «نام ادمین» با DEC-303 جایگزین شد؛ **PRD-04-EP07 (US-07-01، US-07-03، DEC-94)، PRD-04-DD (فرستنده انسانی) و PRD-15 (مدخل «پشتیبان فروشگاه») هنوز متن قبلی را دارند و در گام بعد همگام می‌شوند.** پروتوتایپ: بانک ۵۰ پرسش نمونه بر پایه فایل داده تیم (هرجا مغایر، طبق PRD) با ارجاع خودکار برای پرسش ناشناخته؛ پشتیبان نمایشی پاسخ و درخواست تأیید می‌فرستد. حوزه کالا باز ماند (D-01؛ نمونه پوشاک). | ‏PRD-05a، PRD-05b |\n', s, count=1)
    return s
if len(sys.argv)>1: rw(sys.argv[1],m)
else: rw(A,a); rw(Bb,b)
print('ok')
